set -eu
H=/opt/usr/home/owner; QD=$H/.config/quiet-home; N=quiet-prime-off.service; BK=/opt/usr/share/quiet-tizen-backups/tv-cleanup-20261024
usr(){ env DBUS_SESSION_BUS_ADDRESS=kernel:path=/sys/fs/kdbus/5001-user/bus XDG_RUNTIME_DIR=/run/user/5001 HOME=$H systemctl --user "$@"; }
[ "$(id -u)" = 0 ]; [ -f "$QD/prime-off.sh" ]
cp -a "$QD/prime-off.sh" $BK/prime-off.sh.v5c-before
base64 -d > "$QD/prime-off.sh.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$QD/prime-off.sh.new" | cut -d' ' -f1)" = c9c2652b5993c35bbfc8e59248f15490757879eb545374b15eeebb284b518947 ]
sh -n < "$QD/prime-off.sh.new"
chown owner:users "$QD/prime-off.sh.new"; chmod 644 "$QD/prime-off.sh.new"; chsmack -a User::Home "$QD/prime-off.sh.new"; mv "$QD/prime-off.sh.new" "$QD/prime-off.sh"
usr restart $N; sleep 2; echo "active=$(usr is-active $N)"; tail -n 1 /run/user/5001/quiet-prime-off.log
echo 'JANITOR v5c INSTALLED'
